export interface UserProfile {
  height: number;
  weight?: number;
  level: 'iniciante' | 'intermediario' | 'avancado';
  terrain: 'lazer_urbano' | 'mobilidade' | 'mtb_recreativo' | 'mtb_intermediario' | 'mtb_pesado' | 'estrada' | 'gravel' | 'bmx';
  frequency: 'fds' | '3x_semana' | 'diario';
  budget: 'ate_1500' | 'ate_3000' | '3000_5000' | '5000_10000' | 'acima_10000';
}

export interface RecommendationLink {
  label: string;
  url: string;
}

export interface RecommendationOption {
  category: 'Economica' | 'CustoBeneficio' | 'Avancada';
  title: string;
  brand: string;
  model: string;
  priceRange: string;
  description: string;
  highlights: string[];
  links: RecommendationLink[];
}

export interface IdealSpecs {
  type: string;
  frameSize: string;
  transmission: string;
  brakes: string;
  suspension: string;
  wheelsTires: string;
}

export interface RecommendationResponse {
  summary: string;
  profileAnalysis: string;
  idealSpecs: IdealSpecs;
  options: RecommendationOption[];
  upgrades: string[];
  accessories: string[];
  nextSteps: string[];
  maintenanceTips: string[];
  searchSources?: { title: string; uri: string }[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { UserProfile, RecommendationResponse } from "../types";

export const getBikeRecommendation = async (profile: UserProfile): Promise<RecommendationResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Você é o maior especialista brasileiro em bicicletas.
    Sua missão é recomendar modelos REAIS de bicicletas disponíveis para venda no Brasil (ex: Caloi, Oggi, Sense, Specialized, Scott, Trek, Groove, Swift).

    REGRAS CRÍTICAS:
    1. Use a ferramenta Google Search para encontrar preços ATUAIS e modelos que estejam em estoque.
    2. Indique o Tamanho de Quadro correto para a altura de ${profile.height}cm.
    3. Forneça links diretos para o site da marca ou grandes lojas brasileiras (Netshoes, Centauro, Mercado Livre oficial, ou site da própria fabricante).
    4. Mantenha as sugestões rigorosamente dentro do orçamento: ${profile.budget}.

    FORMATO DE RESPOSTA: JSON.
  `;

  const userPrompt = `
    Analise este perfil e recomende 3 modelos de bikes reais (uma econômica, uma custo-benefício e uma de performance):
    - Altura: ${profile.height} cm
    - Peso: ${profile.weight ? profile.weight + 'kg' : 'Não informado'}
    - Nível: ${profile.level}
    - Terreno: ${profile.terrain}
    - Frequência: ${profile.frequency}
    - Orçamento: ${profile.budget}

    Retorne os links de compra/referência para cada modelo.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [
        { role: 'user', parts: [{ text: userPrompt }] }
      ],
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }],
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            profileAnalysis: { type: Type.STRING },
            idealSpecs: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                frameSize: { type: Type.STRING },
                transmission: { type: Type.STRING },
                brakes: { type: Type.STRING },
                suspension: { type: Type.STRING },
                wheelsTires: { type: Type.STRING },
              },
              required: ["type", "frameSize", "transmission", "brakes", "suspension", "wheelsTires"]
            },
            options: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  category: { type: Type.STRING },
                  title: { type: Type.STRING },
                  brand: { type: Type.STRING },
                  model: { type: Type.STRING },
                  priceRange: { type: Type.STRING },
                  description: { type: Type.STRING },
                  highlights: { type: Type.ARRAY, items: { type: Type.STRING } },
                  links: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        label: { type: Type.STRING },
                        url: { type: Type.STRING }
                      },
                      required: ["label", "url"]
                    }
                  }
                },
                required: ["category", "title", "brand", "model", "priceRange", "description", "highlights", "links"]
              }
            },
            upgrades: { type: Type.ARRAY, items: { type: Type.STRING } },
            accessories: { type: Type.ARRAY, items: { type: Type.STRING } },
            nextSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
            maintenanceTips: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "profileAnalysis", "idealSpecs", "options", "upgrades", "accessories", "nextSteps", "maintenanceTips"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Sem resposta do Gemini");

    const parsed = JSON.parse(text) as RecommendationResponse;

    // Anexar fontes de pesquisa se disponíveis
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      parsed.searchSources = chunks
        .filter((c: any) => c.web)
        .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
    }

    return parsed;
  } catch (error) {
    console.error("Erro ao consultar Gemini:", error);
    throw error;
  }
};

