import { GoogleGenAI, Type } from "@google/genai";
import { UserProfile, RecommendationResponse } from "../types";

export const getBikeRecommendation = async (profile: UserProfile): Promise<RecommendationResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Você é um especialista em bikes no Brasil. Seja ULTRA RÁPIDO e objetivo.
    Gere um projeto de compra REAL com modelos em estoque no Brasil.

    REGRAS DE VELOCIDADE:
    1. Não faça análises longas. Vá direto aos dados.
    2. Use links de busca estáveis (ex: centauro.com.br/busca?q=Nome+Da+Bike).
    3. Categorias: 'Economica' (Entrada), 'CustoBeneficio' (Ideal), 'Avancada' (Pro).
    4. Obrigatório: 3 opções de bikes, upgrades, acessórios e manutenção.

    FORMATO: JSON puro.
  `;

  const userPrompt = `
    Bike para: Altura ${profile.height}cm, Nível ${profile.level}, Terreno ${profile.terrain}, Orçamento ${profile.budget}.
    Gere JSON com: summary, profileAnalysis, idealSpecs, options, upgrades, accessories, maintenanceTips.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }],
        // Desativa o orçamento de pensamento para máxima velocidade de resposta
        thinkingConfig: { thinkingBudget: 0 },
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            profileAnalysis: { type: Type.STRING },
            idealSpecs: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                frameSize: { type: Type.STRING },
                transmission: { type: Type.STRING },
                brakes: { type: Type.STRING },
                suspension: { type: Type.STRING },
                wheelsTires: { type: Type.STRING },
              },
              required: ["type", "frameSize", "transmission", "brakes", "suspension", "wheelsTires"]
            },
            options: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  category: { type: Type.STRING },
                  brand: { type: Type.STRING },
                  model: { type: Type.STRING },
                  priceRange: { type: Type.STRING },
                  description: { type: Type.STRING },
                  highlights: { type: Type.ARRAY, items: { type: Type.STRING } },
                  links: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: { label: { type: Type.STRING }, url: { type: Type.STRING } },
                      required: ["label", "url"]
                    }
                  }
                }
              }
            },
            upgrades: { type: Type.ARRAY, items: { type: Type.STRING } },
            accessories: { type: Type.ARRAY, items: { type: Type.STRING } },
            maintenanceTips: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "profileAnalysis", "idealSpecs", "options", "upgrades", "accessories", "maintenanceTips"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Sem resposta");
    return JSON.parse(text) as RecommendationResponse;
  } catch (error) {
    console.error("Erro na API:", error);
    throw error;
  }
};

